function picks(){const root=$('selections');root.replaceChildren();$('selectedPanel').hidden=!selected.length;for(const p of selected){const row=node('div',p.name);if(room==='foods'){const field=node('input','');field.type='number';field.min='.001';field.max='50000';field.step='any';field.value=p.grams;field.setAttribute('aria-label','Grams for '+p.name);field.oninput=()=>p.grams=field.value;row.append(field)}row.append(button('Remove',()=>{selected=selected.filter(x=>x.id!==p.id);picks()}));root.append(row)}}
