  const primary=!primaryClaimed;let root,controller;
  if(primary){primaryClaimed=true;root=source;controller=initial||createView(root,true);initial=null}
  else{root=pristine.cloneNode(true);root.id='research-view-'+(++serial);for(const element of root.querySelectorAll('[id]')){element.dataset.researchId=element.id;element.id=root.id+'-'+element.id}for(const label of root.querySelectorAll('[for]'))label.htmlFor=root.id+'-'+label.htmlFor;controller=createView(root,false)}
  const marker=document.createComment('research view return');if(primary)root.before(marker);
